import{describe,it,expect,beforeEach}from"vitest";import{ReviewEngine,analyzeSentiment,detectSpam,getTrendingAspects,generateSummary,filterAndSortReviews,averageRating}from"../../frontend/js-modules/reviews/review-engine.js";describe("analyzeSentiment",()=>{it("labels clearly positive text as positive",()=>{const e=analyzeSentiment("This place was amazing, beautiful and the staff were so helpful.");expect(e.label).toBe("positive"),expect(e.score).toBeGreaterThan(0)}),it("labels clearly negative text as negative",()=>{const e=analyzeSentiment("Terrible experience, overpriced, dirty and the guide was rude.");expect(e.label).toBe("negative"),expect(e.score).toBeLessThan(0)}),it("flips sentiment on negation",()=>{const e=analyzeSentiment("This was not good at all.");expect(e.score).toBeLessThanOrEqual(0)}),it("treats empty/neutral text as neutral",()=>{const e=analyzeSentiment("We visited on a Tuesday afternoon.");expect(e.label).toBe("neutral")})}),describe("detectSpam",()=>{it("flags very short reviews",()=>{expect(detectSpam({text:"ok"}).isSpam).toBe(!0)}),it("flags promotional links",()=>{const e=detectSpam({text:"Great trip! Visit www.discount-tours.com for cheap deals now"});expect(e.isSpam).toBe(!0),expect(e.reasons).toContain("promotional_link")}),it("flags excessive caps shouting",()=>{const e=detectSpam({text:"THIS PLACE IS AMAZING AND EVERYONE SHOULD GO NOW"});expect(e.reasons).toContain("excessive_caps")}),it("does not flag a normal, genuine review",()=>{const e=detectSpam({text:"We spent two peaceful days here. The guide was knowledgeable and the fort views at sunset were stunning."});expect(e.isSpam).toBe(!1)})}),describe("getTrendingAspects",()=>{const e=[{text:"The crowd and queues were overwhelming but the view was stunning."},{text:"Too crowded, long queues everywhere, not worth the wait."},{text:"Loved the scenic views and the beautiful architecture here."},{text:"Staff were very helpful and friendly throughout our visit."}];it("surfaces positively-mentioned aspects as highlights",()=>{const{highlights:t}=getTrendingAspects(e);expect(t).toEqual(expect.arrayContaining(["scenery"]))}),it("surfaces negatively-mentioned aspects as concerns",()=>{const{concerns:t}=getTrendingAspects(e);expect(t).toEqual(expect.arrayContaining(["crowd"]))})}),describe("generateSummary",()=>{it("reports a percentage breakdown and highlights/concerns",()=>{const e=generateSummary([{text:"Amazing, beautiful, and the guide was so helpful."},{text:"Wonderful trip, loved every moment, great value."},{text:"Overpriced and the crowd made it hard to enjoy."}]);expect(e.reviewCount).toBe(3),expect(e.positivePct).toBeGreaterThan(0),expect(e.text).toContain("%")}),it("excludes spam-flagged reviews from the summary",()=>{const e=generateSummary([{text:"Amazing trip, beautiful views, highly recommend."},{text:"www.scam-tours.com best deals ever call me now"}]);expect(e.reviewCount).toBe(1)}),it("handles zero reviews gracefully",()=>{const e=generateSummary([]);expect(e.reviewCount).toBe(0),expect(e.text).toMatch(/not enough reviews/i)})}),describe("filterAndSortReviews",()=>{const e=[{id:"a",rating:5,helpfulVotes:2,text:"Amazing and beautiful place, loved it.",createdAt:"2026-01-01"},{id:"b",rating:2,helpfulVotes:10,text:"Terrible, overpriced and dirty.",createdAt:"2026-02-01"},{id:"c",rating:4,helpfulVotes:1,text:"Pretty good visit overall.",createdAt:"2026-03-01"}];it("sorts by helpful votes by default",()=>{const t=filterAndSortReviews(e);expect(t[0].id).toBe("b")}),it("filters by minimum rating",()=>{const t=filterAndSortReviews(e,{minRating:4});expect(t.map(e=>e.id).sort()).toEqual(["a","c"])}),it("filters by sentiment label",()=>{const t=filterAndSortReviews(e,{sentiment:"negative"});expect(t.map(e=>e.id)).toEqual(["b"])}),it("excludes spam from results by default",()=>{const t=[...e,{id:"d",rating:5,text:"www.spamlink.com call me now",helpfulVotes:99}],i=filterAndSortReviews(t);expect(i.find(e=>"d"===e.id)).toBeUndefined()})}),describe("averageRating",()=>{it("averages ratings across non-spam reviews",()=>{expect(averageRating([{rating:5,text:"Great trip, loved it here."},{rating:3,text:"It was fine, nothing special."}])).toBe(4)}),it("returns 0 for no reviews",()=>{expect(averageRating([])).toBe(0)})}),describe("ReviewEngine",()=>{let e;beforeEach(()=>{e=new ReviewEngine}),it("adds a review and validates rating range",()=>{expect(()=>e.addReview({destinationId:"jaipur",text:"Nice place",rating:6})).toThrow()}),it("requires a destinationId",()=>{expect(()=>e.addReview({text:"Nice place",rating:4})).toThrow()}),it("stores and retrieves reviews scoped by destination",()=>{e.addReview({destinationId:"jaipur",author:"Asha",rating:5,text:"Beautiful forts and friendly people."}),e.addReview({destinationId:"goa",author:"Ravi",rating:3,text:"Crowded beaches, average food."}),expect(e.getByDestination("jaipur")).toHaveLength(1),expect(e.getByDestination("goa")).toHaveLength(1)}),it("toggles helpful votes on and off",()=>{const t=e.addReview({destinationId:"jaipur",rating:5,text:"Loved the fort and the views."});e.voteHelpful(t.id,"user1"),expect(e.reviews.find(e=>e.id===t.id).helpfulVotes).toBe(1),e.voteHelpful(t.id,"user1"),expect(e.reviews.find(e=>e.id===t.id).helpfulVotes).toBe(0)}),it("routes spam-flagged reviews into the moderation queue",()=>{e.addReview({destinationId:"jaipur",rating:5,text:"www.freetickets.com dm me now for deals"}),expect(e.getModerationQueue()).toHaveLength(1)}),it("computes a destination summary from stored reviews",()=>{e.addReview({destinationId:"jaipur",rating:5,text:"Amazing fort views and helpful guides."}),e.addReview({destinationId:"jaipur",rating:4,text:"Loved it, though quite crowded at midday."});const t=e.getSummary("jaipur");expect(t.reviewCount).toBe(2),expect(e.getAverageRating("jaipur")).toBe(4.5)})});